package com.cloudmall.cart;
import com.cloudmall.common.api.ApiResponse;import com.cloudmall.common.error.*;import org.springframework.web.bind.annotation.*;import java.util.*;import java.util.concurrent.*;
@RestController @RequestMapping("/api/cart") public class CartController{static final Map<Long,Map<Long,Item>> CART=new ConcurrentHashMap<>();private Map<Long,Item> cart(Long u){return CART.computeIfAbsent(u,k->new ConcurrentHashMap<>());}private Long uid(){return 1L;}
 @GetMapping public ApiResponse<?> all(){return ApiResponse.ok(cart(uid()).values());}@PostMapping("/items") public ApiResponse<?> add(@RequestBody Item i){if(i.skuId==null||i.quantity<1)throw new BizException(ErrorCodes.INVALID,"购物车数量必须为正数",400);Item x=cart(uid()).get(i.skuId);if(x==null)cart(uid()).put(i.skuId,i);else x.quantity+=i.quantity;return ApiResponse.ok(cart(uid()).get(i.skuId));}
 @PutMapping("/items/{skuId}") public ApiResponse<?> update(@PathVariable Long skuId,@RequestBody Item i){if(i.quantity<1)throw new BizException(ErrorCodes.INVALID,"数量必须为正数",400);Item x=cart(uid()).get(skuId);if(x==null)throw new BizException(ErrorCodes.NOT_FOUND,"购物车项不存在",404);x.quantity=i.quantity;return ApiResponse.ok(x);}@DeleteMapping("/items/{skuId}")public ApiResponse<?> del(@PathVariable Long skuId){cart(uid()).remove(skuId);return ApiResponse.ok(null);}
 @PutMapping("/items/{skuId}/checked")public ApiResponse<?> checked(@PathVariable Long skuId,@RequestBody Map<String,Boolean>b){Item x=cart(uid()).get(skuId);if(x==null)throw new BizException(ErrorCodes.NOT_FOUND,"购物车项不存在",404);x.checked=Boolean.TRUE.equals(b.get("checked"));return ApiResponse.ok(x);}@PostMapping("/settlement/preview")public ApiResponse<?> preview(@RequestBody Map<String,List<Long>> b){return ApiResponse.ok(Map.of("items",cart(uid()).values(),"totalAmount","0.00","invalidItems",Collections.emptyList()));}
 public static class Item{public Long skuId;public int quantity=1;public boolean checked;public String addedAt=java.time.OffsetDateTime.now().toString();}}
